// Simulating a database
export type Post = {
  id: number;
  title: string;
};

let posts: Post[] = [
  { id: 1, title: 'First Post' },
];

export async function getPosts(): Promise<Post[]> {
  // Simulate delay
  await new Promise((resolve) => setTimeout(resolve, 100));
  return posts;
}

export async function addPost(title: string) {
  await new Promise((resolve) => setTimeout(resolve, 100));
  posts.push({ id: posts.length + 1, title });
}

import { unstable_cache } from 'next/cache';
import { getPosts as dbGetPosts } from './db';

export const getCachedPosts = unstable_cache(
  async () => {
    return dbGetPosts();
  },
  ['posts-list'], // Key parts
  { tags: ['posts'] } // Tags for revalidation
);

'use server';

import { revalidateTag } from 'next/cache';
import { addPost } from '@/lib/db';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  if (!title) {
    throw new Error('Title is required');
  }

  await addPost(title);

  // Invalidate the cache for the 'posts' tag so fresh data is fetched immediately
  revalidateTag('posts');
}

import { getCachedPosts } from '@/lib/data';
import { createPost } from '@/app/actions';

export default async function Home() {
  const posts = await getCachedPosts();

  return (
    <main>
      <h1>Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>{post.title}</li>
        ))}
      </ul>

      <h2>Create New Post</h2>
      <form action={createPost}>
        <input type="text" name="title" placeholder="Post Title" required />
        <button type="submit">Create Post</button>
      </form>
    </main>
  );
}

